-- Test data. Generated by formulas (no random()), so it is identical everywhere.
-- This lets the checker compare your results with the expected ones.

-- Deterministic "random" number 0..268435455 derived from a string (md5-based)
CREATE FUNCTION pseudo_random(seed text) RETURNS integer
LANGUAGE sql IMMUTABLE
AS $$ SELECT ('x' || substr(md5(seed), 1, 7))::bit(28)::integer $$;

INSERT INTO users (email, name, city, created_at)
SELECT
    'user' || i || '@mail.test',
    (ARRAY['Anna','John','Maria','Oliver','Emma','David','Olivia','Paul','Natalie','Sam',
           'Irene','Alex','Tanya','Max','Julia','Arthur','Sophie','Nick','Daria','Roman'])[(i * 7 % 20) + 1]
        || ' ' ||
    (ARRAY['K.','S.','P.','M.','L.','N.','W.','B.','G.','D.'])[(i * 3 % 10) + 1],
    CASE WHEN i % 11 = 0 THEN NULL
         ELSE (ARRAY['London','Berlin','Paris','Warsaw','Prague','Lisbon'])[(i * 5 % 6) + 1]
    END,
    timestamptz '2025-06-01 00:00:00+00' + make_interval(days => i * 37 % 300, hours => i * 13 % 24)
FROM generate_series(1, 200) AS i;

INSERT INTO venues (name, city, capacity) VALUES
    ('O2 Academy',         'London',  500),
    ('Columbiahalle',      'Berlin',  300),
    ('Olympia',            'Paris',   450),
    ('Progresja',          'Warsaw',  200),
    ('Lucerna Hall',       'Prague',  150),
    ('Coliseu',            'Lisbon',  400),
    ('Soho Theatre',       'London',  120),
    ('Basement Club',      'Berlin',  100);

INSERT INTO events (venue_id, title, category, starts_at, base_price)
SELECT
    (i * 3 % 8) + 1,
    (ARRAY['Concert','Play','Stand-up','Match','Festival'])[(i % 5) + 1] || ' #' || i,
    (ARRAY['concert','theatre','standup','sport','festival'])[(i % 5) + 1],
    timestamptz '2026-03-01 19:00:00+00' + make_interval(days => i * 9 % 240),
    (20 + (i * 17 % 13) * 10 + CASE WHEN i % 3 = 0 THEN 0.5 ELSE 0 END)::numeric(10,2)
FROM generate_series(1, 40) AS i;

INSERT INTO orders (user_id, status, created_at)
SELECT
    -- users 181..200 place no orders; the first 30 users order noticeably more
    CASE WHEN pseudo_random('vip' || i) % 4 = 0 THEN pseudo_random('u' || i) % 30
         ELSE pseudo_random('u' || i) % 180
    END + 1,
    CASE pseudo_random('s' || i) % 13 WHEN 0 THEN 'cancelled' WHEN 1 THEN 'pending' WHEN 2 THEN 'refunded' ELSE 'paid' END,
    timestamptz '2026-01-01 00:00:00+00'
        + make_interval(days => pseudo_random('d' || i) % 290, mins => pseudo_random('m' || i) % 1440)
FROM generate_series(1, 1000) AS i;

INSERT INTO tickets (order_id, event_id, seat_no, price)
SELECT
    o.id,
    o.event_id,
    row_number() OVER (PARTITION BY o.event_id ORDER BY o.id, k),
    CASE WHEN (o.id + k) % 9 = 0 THEN e.base_price * 2 ELSE e.base_price END
FROM (
    SELECT id,
           pseudo_random('e' || id) % 40 + 1 AS event_id,
           pseudo_random('n' || id) % 4 + 1  AS n
    FROM orders
) AS o
JOIN events AS e ON e.id = o.event_id
CROSS JOIN LATERAL generate_series(1, o.n) AS k;

DROP FUNCTION pseudo_random(text);
